import { defaultEmojiDataResolver, type EmojiDataResolver } from "frimousse";

type SearchIndex = Record<string, string[]>;

let searchIndexPromise: Promise<SearchIndex | null> | undefined;

/**
 * Loads `search-index.json` (generated by `pnpm sync:emojibase`) once. It holds
 * the labels and tags of every supported language plus pinyin for Chinese.
 * Returns null on failure and retries on the next load.
 */
function loadSearchIndex(emojibaseUrl: string, signal?: AbortSignal): Promise<SearchIndex | null> {
  searchIndexPromise ??= fetch(`${emojibaseUrl}/search-index.json`, { signal })
    .then((response) => (response.ok ? (response.json() as Promise<SearchIndex>) : null))
    .catch(() => null)
    .then((index) => {
      if (!index) searchIndexPromise = undefined;
      return index;
    });
  return searchIndexPromise;
}

/**
 * Resolves the active locale's Emojibase data and adds search keywords from
 * every other supported language (and pinyin) to each emoji's tags, so e.g.
 * "smile", "웃음" or "xiaolian" all find 😀 whatever the app language is.
 * Displayed labels stay in the active locale. If the index cannot be loaded,
 * the localized data is used as-is.
 */
export const resolveMultilingualEmojiData: EmojiDataResolver = async (locale, options) => {
  const [localized, index] = await Promise.all([
    defaultEmojiDataResolver(locale, options),
    loadSearchIndex(options.emojibaseUrl ?? "", options.signal),
  ]);
  if (!index) return localized;

  return {
    ...localized,
    emojis: localized.emojis.map((entry) => {
      const keywords = index[entry.emoji];
      if (!keywords) return entry;
      const own = new Set([
        entry.label.toLowerCase(),
        ...entry.tags.map((tag) => tag.toLowerCase()),
      ]);
      const extra = keywords.filter((keyword) => !own.has(keyword));
      return extra.length > 0 ? { ...entry, tags: [...entry.tags, ...extra] } : entry;
    }),
  };
};
